-- 用ID列表批量查找，再用field函数确保顺序不变
SELECT * FROM user
WHERE id IN

    #{id}

ORDER BY FIELD(id,

    #{id}
 asc
)

select exists(
    select *
    from focus f1, focus f2
    where f1.user_id1=f2.user_id2 and f1.user_id2=f2.user_id1
      and f1.user_id1=#{user_id} and f1.user_id2=#{focus_user_id}
)
